import{_ as i,o as n,c as t,a3 as s}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Pumpkin plugin signing","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/signing/docs/index.md"},"headers":[],"relativePath":"tools/signing/docs/index.md","filePath":"tools/signing/docs/index.md","lastUpdated":1791428389000}'),a={name:"tools/signing/docs/index.md"};function o(d,e,r,p,c,g){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="pumpkin-plugin-signing" tabindex="-1">Pumpkin plugin signing <a class="header-anchor" href="#pumpkin-plugin-signing" aria-label="Permalink to &quot;Pumpkin plugin signing&quot;">​</a></h1><p><code>@pumpkin-plugins/signing</code> signs and verifies Pumpkin <code>.wasm</code> components with Ed25519 metadata. Use <code>signWasm</code> and <code>verifyWasm</code> when integrating signing into repository tooling; the GitHub Actions provide a ready-made workflow step for release pipelines.</p><h2 id="signed-file-contents" tabindex="-1">Signed file contents <a class="header-anchor" href="#signed-file-contents" aria-label="Permalink to &quot;Signed file contents&quot;">​</a></h2><p>Signing appends Pumpkin metadata and signature custom sections to the WebAssembly file. Verification checks the signature against the module bytes and embedded metadata and reports the signing key and release fields. Signing sections can be stripped or parsed when a tool needs to inspect or replace them. Existing signature sections are replaced when producing a new signature.</p><p>The key is a 32-byte Ed25519 seed, represented in workflows as 64 hexadecimal characters. Keep the secret key in a protected secret store; publish the public key through a separately trusted channel so consumers can pin the expected signer. A valid signature proves the file matches its metadata, but trust depends on how the public key was obtained.</p><p>Use the action interface for one-file or manifest-based CI signing and verification. These helpers do not build plugins; sign the exact <code>.wasm</code> artifact produced by the build job.</p>',6)])])}const h=i(a,[["render",o]]);export{u as __pageData,h as default};
